// Роль עובד מחסן — через «כניסה כעובד» из admin-сессии, в конце «חזרה לחשבון הניהול».
import { test, expect, Page } from '@playwright/test';
import * as path from 'path';

const auth = (role: string) => path.resolve(__dirname, '../../../auth', `${role}.json`);
test.use({ storageState: auth('admin') });

async function impersonate(page: Page, employee: string) {
  await page.goto('/team');
  await expect(page.getByRole('heading', { name: 'צוות והרשאות' })).toBeVisible();
  const row = page
    .locator('div')
    .filter({ hasText: employee })
    .filter({ has: page.getByRole('button', { name: 'פעולות' }) })
    .last();
  await row.getByRole('button', { name: 'פעולות' }).click();
  await page.getByRole('menuitem', { name: 'כניסה כעובד' }).click();
  await page.getByRole('dialog').getByRole('button', { name: 'כניסה', exact: true }).click();
  await expect(page.getByText(`מחובר/ת כרגע בתור ${employee} — כניסה כעובד פעילה`)).toBeVisible({ timeout: 20_000 });
}

async function backToAdmin(page: Page) {
  await page.getByText('חזרה לחשבון הניהול').click();
  await expect(page.getByText('test admin').first()).toBeVisible({ timeout: 20_000 });
}

test.describe('picking — תצוגות (קריאה בלבד)', () => {
  test('ליקוט וניתוב: קיבוץ לפי מקום, «ללא מיקום» בסוף, מצב ללא בחירה #6a5cb979 @desktop @prod-safe', async ({ page }) => {
    await impersonate(page, 'עובד מחסן בדיקה');
    await page.goto('/warehouse/picking');
    await expect(page.getByRole('heading', { level: 1, name: 'ליקוט וניתוב' })).toBeVisible({ timeout: 20_000 });
    await expect(
      page.getByText('הפריטים מקובצים לפי מקום ולפי פריט האחסון — סדר המעבר ביניהם נתון לכם; פריט ללא מיקום מגיע בסוף'),
    ).toBeVisible();
    await expect(page.getByRole('heading', { level: 2, name: 'הזמנות' })).toBeVisible();
    await expect(page.getByText(/^\d+ הזמנות ממתינות לליקוט$|^אין הזמנות/).first()).toBeVisible();
    await expect(page.getByRole('heading', { level: 2, name: 'מפת המחסן' })).toBeVisible();
    await expect(page.getByText('בחרו הזמנה כדי לראות את הפריטים והמיקומים שלהם על המפה, ולהתחיל בליקוט.')).toBeVisible();
    await expect(page).not.toHaveURL(/order=/); // ничего не выбрано автоматически
    await backToAdmin(page);
  });

  test('מפת המחסן: מדף ריק מציג «המדף ריק · טרם נקלט אליו מלאי» #6a7192ed @desktop @prod-safe', async ({ page }) => {
    await page.goto('/warehouse/map');
    await expect(page.getByRole('heading', { level: 1, name: 'מפת המחסן' })).toBeVisible({ timeout: 20_000 });
    const emptyStorage = page.getByRole('button', { name: / ריק$/ }).first();
    await expect(emptyStorage).toBeVisible({ timeout: 20_000 });
    await emptyStorage.click();
    const emptyShelf = page.getByRole('listitem').getByRole('button', { name: / ריק$/ }).first();
    await emptyShelf.click();
    await expect(page.getByRole('heading', { level: 2, name: /^תכולת/ })).toBeVisible();
    await expect(page.getByText('המדף ריק').filter({ visible: true })).toBeVisible();
    await expect(page.getByText('טרם נקלט אליו מלאי.').filter({ visible: true })).toBeVisible();
  });

  test('בחירת אסטרטגיית מסלול (סריאלי/אזורי/גלי) למחסן ולהזמנה #6a5cb979 @desktop', async () => {
    test.skip(true, 'UI выбора стратегии не найден (находка pick-08); стратегию реального склада не меняем');
  });
});
